//		Exec(ctx)
func (u *SSLRecordUpsertBulk) UpdateNewValues() *SSLRecordUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(sslrecord.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(sslrecord.FieldCreatedAt)
			}
			if _, exists := b.mutation.ConfigID(); exists {
				s.SetIgnore(sslrecord.FieldConfigID)
			}
			if _, exists := b.mutation.Domain(); exists {
				s.SetIgnore(sslrecord.FieldDomain)
			}
		}
	}))
	return u
}

